#!/usr/bin/env python3"""Fix the collapsed line 728 in bin/agent/prompts.py."""from pathlib import Pathfilepath = Path("bin/agent/prompts.py")content = filepath.read_text(encoding="utf-8")# The replacement: properly formatted _serialize_element + _write_prompts_xml, no _indentnew_block = '''def _serialize_element(element: ET.Element, level: int = 0) -> str:    """Serialize an element to XML, using CDATA for value elements."""    indent = "  " * level    parts: list[str] = []    attrs = "".join(f' {k}="{v}' for k, v in element.attrib.items())    if len(element) == 0 and (element.text is None or not element.text.strip()):        if element.tag:            parts.append(f"{indent}<{element.tag}{attrs} />")        return "".join(parts)    parts.append(f"{indent}<{element.tag}{attrs}>")    if element.tag == "value" and element.text is not None:        cdata = element.text.replace("]]>", "]]]]><![CDATA[>")        parts.append(f"<![CDATA[{cdata}]]>")    elif element.text:        parts.append(element.text)    for child in element:        parts.append("\\n")        parts.append(_serialize_element(child, level + 1))    if len(element) > 0:        parts.append(f"\\n{indent}")    parts.append(f"</{element.tag}>")    return "".join(parts)def _write_prompts_xml(tree: ET.ElementTree, path: Path) -> None:    """Write the prompts XML with CDATA sections for all value elements."""    root = tree.getroot()    xml_str = '<?xml version="1.0" encoding="utf-8"?>\\n'    xml_str += _serialize_element(root)    xml_str += "\\n"    path.write_text(xml_str, encoding="utf-8")'''# Find the collapsed line that starts with "def _serialize_element" and ends with the _indent body# We need to find from "def _serialize_element" up to and including the _indent function bodylines = content.split('\n')for i, line in enumerate(lines):    if line.startswith('def _serialize_element(element: ET.Element, level: int = 0) -> str:    """'):        # Found the collapsed line - it's line index i (line 728 in 1-indexed)        # This line contains _serialize_element, _write_prompts_xml, and two def _indent headers        # plus the start of _indent body: spaces = "\n" + level * "  "        # Lines i+1 through i+10 contain the rest of _indent body        # Find where _indent body ends (before the next def _prompt_node)        end_idx = i        for j in range(i + 1, min(i + 20, len(lines))):            if lines[j].strip().startswith('def _prompt_node'):                end_idx = j - 1                # Also remove trailing empty lines                while end_idx > i and lines[end_idx].strip() == '':                    end_idx -= 1                break                # Build the replacement        new_lines = lines[:i] + new_block.rstrip('\n').split('\n') + [''] + [''] + lines[end_idx + 1:]        content = '\n'.join(new_lines)        print(f"Replaced lines {i+1} through {end_idx+1}")        breakelse:    print("ERROR: Could not find the collapsed _serialize_element line")    import sys    sys.exit(1)filepath.write_text(content, encoding="utf-8")print("File written successfully")